def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    doughnut_patches = image_patch.find("doughnut")
    if not doughnut_patches: return image_patch

    # Sort by depth to find the closest doughnuts
    doughnut_patches.sort(key=lambda p: p.compute_depth())

    # Check for overlapping doughnuts
    for i in range(len(doughnut_patches) - 1):
        for j in range(i + 1, len(doughnut_patches)):
            if doughnut_patches[i].overlaps_with(doughnut_patches[j].left, doughnut_patches[j].lower, doughnut_patches[j].right, doughnut_patches[j].upper):
                return doughnut_patches[i]
    return doughnut_patches[0]

