    doughnuts = image_patch.find("doughnut")
    if not doughnuts: return image_patch

    # Sort doughnuts by their vertical center to get the topmost one first
    doughnuts.sort(key=lambda d: d.vertical_center)

    # Check which doughnut is partially laying on another
    for i in range(len(doughnuts)):
        for j in range(i + 1, len(doughnuts)):
            if doughnuts[i].overlaps_with(*doughnuts[j].bounding_box()):
                return doughnuts[i] if i < j else doughnuts[j]

    return doughnuts[0]

